const ids = ["G01","G02","G03","G04","G05","G06"];
const packets = await Promise.all(ids.map(id => tools.origin_packet({case_id:id})));
const all = {};
for (const r of packets) {
  const c = r.cases[0];
  const ev = c.evidence;
  const sourceById = {};
  for (const m of ev.material_index) sourceById[m.id] = m.source_id;
  const parents = {};
  for (const l of ev.links) {
    if (l.relation !== "derivation") continue;
    (parents[l.child] ||= []).push(l.parent);
  }
  const itemById = {};
  for (const it of ev.items) itemById[it.id] = it;
  // add any ids from items/links not in index
  const allIds = new Set([...Object.keys(sourceById), ...Object.keys(itemById), ...Object.keys(parents), ...ev.links.map(l=>l.parent)]);
  const memo = {};
  const visiting = new Set();
  function resolve(id) {
    if (memo[id]) return memo[id];
    if (visiting.has(id)) return new Set(); // cycle guard
    visiting.add(id);
    const ps = (parents[id]||[]).filter(p => allIds.has(p));
    let out;
    if (ps.length === 0) {
      out = new Set(sourceById[id] ? [sourceById[id]] : []);
    } else {
      out = new Set();
      for (const p of ps) for (const o of resolve(p)) out.add(o);
    }
    visiting.delete(id);
    memo[id] = out;
    return out;
  }
  const unionAll = new Set();
  for (const id of allIds) for (const o of resolve(id)) unionAll.add(o);
  const disc = [];
  for (const id of allIds) {
    const it = itemById[id];
    if (it && it.origins) {
      const a = [...resolve(id)].sort().join(",");
      const b = [...it.origins].sort().join(",");
      if (a !== b) disc.push({id, computed:[...resolve(id)], item:it.origins});
    }
  }
  all[c.id] = {case:c, sourceById, parents, itemById, allIds, resolve, unionAll, disc};
  console.log("===",c.id,"===");
  console.log("materials", ev.material_count, "allIds", allIds.size, "recorded_count", ev.recorded_origin_count, "recorded", ev.recorded_origins);
  console.log("computed union size", unionAll.size, [...unionAll]);
  console.log("discrepancies", JSON.stringify(disc));
  console.log("roots", [...allIds].filter(id=>(parents[id]||[]).length===0 || (parents[id]||[]).every(p=>!allIds.has(p))).map(id=>({id, src:sourceById[id], item:!!itemById[id]})));
}

const ids = ["G01","G02","G03","G04","G05","G06"];
const packets = await Promise.all(ids.map(id => tools.origin_packet({case_id:id})));
const cases = [];
for (const r of packets) {
  const c = r.cases[0];
  const ev = c.evidence;
  const sourceById = {};
  for (const m of ev.material_index) sourceById[m.id] = m.source_id;
  const parents = {};
  for (const l of ev.links) if (l.relation === "derivation") (parents[l.child] ||= []).push(l.parent);
  const allIds = new Set([...Object.keys(sourceById), ...ev.items.map(i=>i.id), ...Object.keys(parents), ...ev.links.map(l=>l.parent)]);
  const memo = {};
  function resolve(id) {
    if (memo[id]) return memo[id];
    const ps = (parents[id]||[]).filter(p=>allIds.has(p));
    const out = new Set();
    if (ps.length === 0) { if (sourceById[id]) out.add(sourceById[id]); }
    else for (const p of ps) for (const o of resolve(p)) out.add(o);
    memo[id] = out;
    return out;
  }
  const unionAll = new Set();
  for (const id of allIds) for (const o of resolve(id)) unionAll.add(o);
  cases.push({
    id: c.id,
    recorded_origin_count: unionAll.size,
    independence: "unknown",
    queries: c.query_ids.map(q => ({material_id:q, origins:[...resolve(q)].sort()}))
  });
}
console.log(JSON.stringify({cases}, null, 2));
